<template><AppShell><StatePanel v-if="loading||error" :loading="loading" :error="error" @retry="load"/><template v-else-if="event"><view class="detail-crumb"><button class="text-button" @tap="go('person',{id:event.person_id})">← {{personName}}档案</button><text>历史阅读片段</text></view><view class="event-cover"><text class="eyebrow">{{event.stage}} / 历史片段</text><text class="event-cover-date">{{event.date_text}}</text><text class="page-title">{{event.title}}</text><view class="event-cover-meta"><text>{{personName}}</text><text>{{event.place||'具体地点整理中'}}</text><text>保留日期原精度</text></view></view><view class="event-reading" :class="{'reading-large':large}"><view class="article-intro"><text class="eyebrow">一段记载</text><text class="article-lead">{{event.summary}}</text></view><view class="article-rule"><text>史料摘读</text><text>{{event.sources.length}} 份来源</text></view><view v-for="(fact,i) in event.facts" :key="fact.id" class="article-paragraph"><text class="paragraph-index">{{String(i+1).padStart(2,'0')}}</text><view><text class="reading-body">{{fact.text}}</text><button class="citation" @tap="sourceId=fact.source_id">{{event.sources.find(s=>s.id===fact.source_id)?.title||'原始资料'}} · {{fact.location}} ↗</button></view></view><view class="event-context"><view><text class="eyebrow">背景</text><text>{{event.background||'相关背景资料仍在整理，暂不补写未经查证的叙事。'}}</text></view><view><text class="eyebrow">结果与影响</text><text>{{event.result||'现有来源支持的具体事实见上文，延伸影响持续补证。'}}</text></view></view><view class="article-rule"><text>继续读，继续求证</text></view><view class="event-sources"><button v-for="s in event.sources" :key="s.id" class="source-row" @tap="sourceId=s.id"><text class="source-row-index">文献</text><view><text>{{s.title}}</text><text class="small">{{s.publisher}}</text></view><text>↗</text></button></view><button class="outline full" @tap="save">{{saved?'移除本机书签':'将这段阅读加入本机书签'}}</button><text class="copy-note">书签仅存本机 · 转发可使用微信右上角菜单</text></view><view class="card"><button class="outline" @tap="go('discussion',{topicId:event.id})">分享阅读感受 · 评论先审核</button></view><view class="card"><text class="serif">读完片段，继续探索</text><button v-if="challengeGroup(event.person_id)" class="outline" @tap="go('learning',{group:challengeGroup(event.person_id)})">试试人物主题挑战</button><button class="outline" @tap="go('assistant',{person_id:event.person_id,name:personName})">问小迹 · 理解人物背景</button></view></template><SourceSheet :source-id="sourceId" @close="sourceId=''"/></AppShell></template>
<script setup>
import {challengeGroup} from '../../lib/learning.js';import {ref} from 'vue';import {onLoad,onShow,onShareAppMessage} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import StatePanel from '../../components/StatePanel.vue';import SourceSheet from '../../components/SourceSheet.vue';import {api} from '../../lib/api.js';import {go} from '../../lib/navigation.js';import {remember,toggleBookmark,isSaved,prefs} from '../../lib/reading.js'
const event=ref(null),personName=ref('人物'),loading=ref(true),error=ref(''),sourceId=ref(''),saved=ref(false),large=ref(false);let id=''
async function load(){loading.value=true;error.value='';try{event.value=await api('events/'+id);const p=await api('people/'+event.value.person_id);personName.value=p.name;remember('event',id,p.name+' · '+event.value.title);saved.value=isSaved('event',id)}catch(e){error.value=e.message}finally{loading.value=false}}
function save(){saved.value=toggleBookmark('event',id,personName.value+' · '+event.value.title)}
onLoad(options=>{id=options.id||'EV-P009-F-008';load()});onShow(()=>large.value=prefs().size==='large');onShareAppMessage(()=>({title:personName.value+' · '+(event.value?.title||'历史片段'),path:'/pages/event/index?id='+id}))
</script>
